// Situação das cópias da coleção: livres, parcialmente usadas ou todas presas em outros decks.
$stockLine=function(array $card): string {
    $owned=(int)($card['owned']??0);
    if($owned<1) return '<p class="builder-stock is-missing">Fora da coleção</p>';
    $used=(int)($card['used_elsewhere']??0); $free=max(0,$owned-$used);
    $decks=array_map(fn($d)=>'<a href="/decks.php?deck='.$d['id'].'&amp;view=selection&amp;stage=deck">'.h($d['name']).'</a>'.($d['quantity']>1?' ('.$d['quantity'].')':''),$card['used_decks']??[]);
    $copies=fn(int $n)=>$n.($n===1?' cópia':' cópias');
    if(!$used) return '<p class="builder-stock is-available">'.$copies($owned).' na coleção · '.($owned===1?'livre':'todas livres').'</p>';
    $where=' Em uso: '.implode(', ',$decks).'.';
    if($free>0) return '<p class="builder-stock is-limited">'.$copies($owned).' na coleção · '.$free.($free===1?' livre':' livres').'.'.$where.'</p>';
    return '<p class="builder-stock is-reserved">'.($owned===1?'Sua cópia já está':'Todas as '.$owned.' cópias já estão').' em outro deck.'.$where.'</p>';
};
$baseSorts=['relevance'=>'Disponibilidade e relevância','name'=>'Nome','newest'=>'Mais recentes','owned'=>'Mais cópias na coleção'];
$sortOptions=$choosingCommander
    ? ['popular'=>'Mais populares']+$baseSorts
    : ($commander && $fmt['edhrec'] ? ['synergy'=>'Maior sinergia','fit'=>'Encaixa no deck (coleção)']+$baseSorts
        : ($hasMeta ? ['meta'=>'Mais jogadas no formato','synergy'=>'Combina com o deck (meta)','fit'=>'Encaixa no deck (coleção)']+$baseSorts : ['fit'=>'Encaixa no deck (coleção)']+$baseSorts));
$leaderName = $fmt['leader']==='oathbreaker' ? 'o oathbreaker' : 'a comandante';
?>
