        <label class="filter-availability">Disponibilidade<select name="availability" <?= $fitMode?'disabled title="O modo Encaixa no deck usa só a sua coleção"':'' ?>><option value="all" <?= $availability==='all'?'selected':'' ?>>Todas as cartas</option><option value="owned" <?= $availability==='owned'?'selected':'' ?>>Somente minha coleção</option><?php if(!$choosingCommander): ?><option value="free" <?= $availability==='free'?'selected':'' ?>>Minha coleção, com cópia livre</option><?php endif; ?><option value="missing" <?= $availability==='missing'?'selected':'' ?>>Fora da coleção</option></select></label>
        <?php if(!$choosingCommander): ?><label class="builder-check"><input type="checkbox" name="colors" value="1" <?= $colorsOnly?'checked':'' ?> <?= $fitMode?'disabled':'' ?>> <?= $hasLeader ? 'Somente identidade d'.($fmt['leader']==='oathbreaker'?'o oathbreaker':'a comandante') : 'Somente as cores do deck'.($identity?'':' (ainda sem cartas)') ?></label><label class="builder-check"><input type="checkbox" name="legal_only" value="1" <?= $legalOnly?'checked':'' ?> <?= $fitMode?'disabled':'' ?>> Somente legais no <?= h($fmt['name']) ?></label><label class="builder-check"><input type="checkbox" name="hide_selected" value="1" <?= $hideSelected?'checked':'' ?> <?= $fitMode?'disabled':'' ?>> Ocultar cartas já no deck ou nas candidatas</label><?php if($fitMode): ?><input type="hidden" name="availability" value="owned"><input type="hidden" name="colors" value="1"><input type="hidden" name="hide_selected" value="1"><input type="hidden" name="legal_only" value="1"><?php endif; ?><?php endif; ?>
        <button class="primary-link">Aplicar filtros</button><a href="<?= h($clearUrl) ?>">Limpar</a>
    </div>
    <details class="filter-advanced" <?= $advancedOpen?'open':'' ?>><summary>Mais filtros</summary>
        <div class="filter-advanced-grid">
