ink['stage']==='candidate'?' · candidata':'') ?></strong><?php foreach($link['gives'] as $reason): ?><span class="fit-preview-reason" style="--relation-color:<?= h(DECK_RELATION_GROUPS[$reason['group']][1]??'#59625f') ?>"><b class="relation-chip"><?= h($reason['label']) ?></b>Esta carta <?= h($reason['give']) ?> → <?= h($link['name']) ?> <?= h($reason['take']) ?><q><?= h($reason['to_text']) ?></q></span><?php endforeach; ?><?php foreach($link['takes'] as $reason): ?><span class="fit-preview-reason" style="--relation-color:<?= h(DECK_RELATION_GROUPS[$reason['group']][1]??'#59625f') ?>"><b class="relation-chip"><?= h($reason['label']) ?></b><?= h($link['name']) ?> <?= h($reason['give']) ?> → esta carta <?= h($reason['take']) ?><q><?= h($reason['from_text']) ?></q></span><?php endforeach; ?></li><?php endforeach; ?><?php if(count($fit['links'])>8): ?><li class="fit-preview-more">+<?= count($fit['links'])-8 ?> outras relações no quadro depois de adicionar.</li><?php endif; ?></ul></details><?php else: ?><p class="fit-preview-none">Nenhuma relação direta com a seleção atual.</p><?php endif; ?><?php endif; ?><p class="muted"><?= deckHighlight((string)($card['type_line']??''),$highlightTerms) ?> · <?= manaSymbols($card['mana_cost']??null) ?></p><div class="builder-oracle"><p><?= nl2br(deckHighlight(deckText($card),$highlightTerms)) ?></p><?php foreach($terms as $term): if(stripos(deckText($card),$term)!==false): ?><small>Contém “<?= h($term) ?>” no Oracle.</small><?php endif; endforeach; ?></div><form method="post"><?php $tokenFields($choosingCommander?'commander':($choosingSignature?'signature':'add'),$card['id']); $filterHidden(); ?><button class="secondary-link" <?= $already && !$choosingSignature?'disabled':'' ?>><?= $choosingCommander?($fmt['leader']==='oathbreaker'?'Escolher como oathbreaker':'Escolher comandante'):($choosingSignature?'Escolher como feitiço de assinatura':($already?'Já adicionada · '.mb_strtolower(deckStageLabel($already['stage'])):'Adicionar às candidatas')) ?></button></form></div></article><?php endforeach; ?></div>
